        return {"method": "diff_xcorr", "peak_lag": None, "r": None,
                "p_value": None, "significant": False, "note": "NaN in data"}
    dx, dy = np.diff(x), np.diff(y)
    n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
